 1→/**
 2→ * Minimal static file server for multi-locale production builds.
 3→ * Serves the Angular i18n output from dist/guitar-trainer/browser/
 4→ * with locale-prefixed paths: /en/, /nl/, /de/.
 5→ *
 6→ * Usage: node e2e/serve-i18n.mjs [port]
 7→ */
 8→import { createServer } from 'node:http';
 9→import { readFile } from 'node:fs/promises';
10→import { resolve, extname } from 'node:path';
11→import { existsSync } from 'node:fs';
12→
13→const PORT = parseInt(process.argv[2] || '4201', 10);
14→const DIST_DIR = resolve(import.meta.dirname, '..', 'dist', 'guitar-trainer', 'browser');
15→const LOCALES = ['en', 'nl', 'de'];
16→
17→const MIME_TYPES = {
18→  '.html': 'text/html; charset=utf-8',
19→  '.js': 'application/javascript; charset=utf-8',
20→  '.css': 'text/css; charset=utf-8',
21→  '.json': 'application/json; charset=utf-8',
22→  '.ico': 'image/x-icon',
23→  '.png': 'image/png',
24→  '.svg': 'image/svg+xml',
25→  '.woff2': 'font/woff2',
26→  '.woff': 'font/woff',
27→};
28→
29→const server = createServer(async (req, res) => {
30→  const url = new URL(req.url, `http://localhost:${PORT}`);
31→  let pathname = url.pathname;
32→
33→  // Redirect root to /en/
34→  if (pathname === '/') {
35→    res.writeHead(302, { Location: '/en/' });
36→    res.end();
37→    return;
38→  }
39→
40→  // Determine locale from path
41→  const localeMatch = pathname.match(/^\/(en|nl|de)(\/.*)?$/);
42→  if (!localeMatch) {
43→    res.writeHead(404, { 'Content-Type': 'text/plain' });
44→    res.end('Not found');
45→    return;
46→  }
47→
48→  const locale = localeMatch[1];
49→  let filePath = localeMatch[2] || '/';
50→
51→  // Remove trailing slash for file lookup, but keep /index.html for directories
52→  if (filePath.endsWith('/')) {
53→    filePath += 'index.html';
54→  }
55→
56→  const fullPath = resolve(DIST_DIR, locale, filePath.slice(1));
57→
58→  // Guard against path traversal: resolved path must stay within DIST_DIR
59→  if (!fullPath.startsWith(DIST_DIR + '/')) {
60→    res.writeHead(400, { 'Content-Type': 'text/plain' });
61→    res.end('Bad request');
62→    return;
63→  }
64→
65→  // If file doesn't exist, serve index.html for SPA routing
66→  const actualPath = existsSync(fullPath) ? fullPath : resolve(DIST_DIR, locale, 'index.html');
67→
68→  // Guard the fallback path as well
69→  if (!actualPath.startsWith(DIST_DIR + '/')) {
70→    res.writeHead(400, { 'Content-Type': 'text/plain' });
71→    res.end('Bad request');
72→    return;
73→  }
74→
75→  try {
76→    const content = await readFile(actualPath);
77→    const ext = extname(actualPath);
78→    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
79→    res.writeHead(200, { 'Content-Type': contentType });
80→    res.end(content);
81→  } catch {
82→    res.writeHead(404, { 'Content-Type': 'text/plain' });
83→    res.end('Not found');
84→  }
85→});
86→
87→server.listen(PORT, () => {
88→  console.log(`i18n server listening on http://localhost:${PORT}`);
89→  console.log(`Serving locales: ${LOCALES.join(', ')} from ${DIST_DIR}`);
90→});
91→

