 1→import { inject, Injectable, OnDestroy, signal } from '@angular/core';
 2→import { FretNote } from './note-data';
 3→import { ProgressionService } from './progression.service';
 4→
 5→export enum GameState {
 6→  IDLE = 'IDLE',
 7→  SHOW_NOTE = 'SHOW_NOTE',
 8→  SHOW_ANSWER = 'SHOW_ANSWER',
 9→}
10→
11→export const SHOW_NOTE_DURATION_MS = 5000;
12→export const SHOW_ANSWER_DURATION_MS = 3000;
13→
14→/**
15→ * Manages the fretboard flash game state machine (IDLE -> SHOW_NOTE -> SHOW_ANSWER cycle).
16→ *
17→ * This service must remain component-provided (not `providedIn: 'root'`) because it
18→ * implements OnDestroy to clean up timers, which only fires for component-scoped providers.
19→ */
20→@Injectable()
21→export class GameStateService implements OnDestroy {
22→  private readonly progression = inject(ProgressionService);
23→
24→  private readonly _state = signal<GameState>(GameState.IDLE);
25→  private readonly _currentNote = signal<FretNote | null>(null);
26→  private timerId: ReturnType<typeof setTimeout> | null = null;
27→
28→  readonly state = this._state.asReadonly();
29→  readonly currentNote = this._currentNote.asReadonly();
30→
31→  start(): void {
32→    if (this._state() !== GameState.IDLE) {
33→      return;
34→    }
35→    this._currentNote.set(this.progression.drawNote());
36→    this._state.set(GameState.SHOW_NOTE);
37→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
38→  }
39→
40→  showAnswer(): void {
41→    if (this._state() !== GameState.SHOW_NOTE) {
42→      return;
43→    }
44→    this.clearTimer();
45→    this._state.set(GameState.SHOW_ANSWER);
46→    this.startTimer(SHOW_ANSWER_DURATION_MS, () => this.nextNote());
47→  }
48→
49→  nextNote(): void {
50→    if (this._state() !== GameState.SHOW_ANSWER) {
51→      return;
52→    }
53→    this.clearTimer();
54→    this._currentNote.set(this.progression.drawNote());
55→    this._state.set(GameState.SHOW_NOTE);
56→    this.startTimer(SHOW_NOTE_DURATION_MS, () => this.showAnswer());
57→  }
58→
59→  stop(): void {
60→    this.clearTimer();
61→    this._currentNote.set(null);
62→    this._state.set(GameState.IDLE);
63→    this.progression.reset();
64→  }
65→
66→  ngOnDestroy(): void {
67→    this.clearTimer();
68→  }
69→
70→  private startTimer(durationMs: number, callback: () => void): void {
71→    this.clearTimer();
72→    this.timerId = setTimeout(callback, durationMs);
73→  }
74→
75→  private clearTimer(): void {
76→    if (this.timerId !== null) {
77→      clearTimeout(this.timerId);
78→      this.timerId = null;
79→    }
80→  }
81→}
